# Web Creator projects: each has a live lab (starter, solution, missions with auto-tests).
def M(say,hint,test): return {'say':say,'hint':hint,'test':test}
def WP(id,title,emoji,level,themes,hook,problem,learn,steps,chips,shelf,starter,solution,missions,ask,remix,kind='html'):
    return {'id':id,'kind':'web','title':title,'emoji':emoji,'level':level,'themes':themes,'hook':hook,'problem':problem,'learn':learn,
      'steps':[{'t':a,'b':b} for a,b in steps],'missions':[{'t':m['say']} for m in missions],'ask':ask,'remix':remix,'showcase':False,'creator':True,
      'lab':{'kind':kind,'chips':chips,'shelf':[{'l':a,'i':b} for a,b in shelf],'starter':starter,'solution':solution,'missions':missions}}
HEAD="<!DOCTYPE html>\n<html>\n<head>\n"
W=[]
# ---------- 1 HTML beginner
W.append(WP('my-world-passport','My Passport to the World','🛂',1,['naija-world','fun'],
 'Make a web page that is your own passport. Stamp the countries you dream of!',
 'Every website starts with a page. A passport page is a fun way to learn the frame and the tags.',
 ['The page frame: head and body','Headings, lists and links'],
 [('Name your page','The <title> goes in the head. It shows on the browser tab.'),('Big heading','<h1> is the biggest heading. Put your name in it.'),('A list of countries','<ul> makes a list. Each country is an <li>.'),('A link','<a href="https://..."> makes a link people can tap.')],
 ['HTML'],[('<title>','<title>|</title>'),('<h1>','<h1>|</h1>'),('<ul>','<ul>\n  <li>|</li>\n</ul>'),('<a>','<a href="https://www.wikipedia.org">|</a>')],
 HEAD+"  <!-- 1: add a <title> -->\n\n</head>\n<body>\n  <!-- 2: add an <h1> with your name -->\n\n  <!-- 3: add a list (ul) with 3 countries (li) -->\n\n  <!-- 4: add a link (a) to a website -->\n\n</body>\n</html>",
 HEAD+"  <title>My Passport</title>\n</head>\n<body>\n  <h1>Passport of Ada</h1>\n  <p>Countries I want to visit:</p>\n  <ul>\n    <li>Japan</li>\n    <li>Brazil</li>\n    <li>Egypt</li>\n  </ul>\n  <a href=\"https://www.wikipedia.org\">Read about the world</a>\n</body>\n</html>",
 [M('Put a <title> in the <head>.','<title>My Passport</title> goes between <head> and </head>.',"return t.has('head > title') && t.text('title').length>2"),
  M('Add an <h1> with your name.','<h1>Passport of ...</h1> goes in the <body>.',"return t.has('body h1') && t.text('h1').length>2"),
  M('Make a list with at least 3 <li> countries.','Use <ul>, then one <li> for each country.',"return t.count('ul > li')>=3 && t.all('ul > li').every(function(l){return l.textContent.trim().length>1})"),
  M('Add a link with <a href="...">.','<a href="https://www.wikipedia.org">words</a>',"return t.has('a[href]') && t.text('a').length>1")],
 'Ask 3 friends: which country would you visit first? Why?','Add a second list: foods from each country.'))
# ---------- 2
W.append(WP('jollof-vs-the-world','Jollof Meets the World','🍛',1,['naija-world','fun'],
 'Write a recipe card for jollof and a dish from another country.',
 'Recipes are lists in a clear order. HTML has special tags for steps.',
 ['Numbered lists','Bold words','Sub-headings'],
 [('Two headings','<h2> makes a smaller heading. Use one for each dish.'),('Numbered steps','<ol> numbers the steps. Each step is an <li>.'),('Bold the key words','<strong> makes words bold.')],
 ['HTML'],[('<h2>','<h2>|</h2>'),('<ol>','<ol>\n  <li>|</li>\n</ol>'),('<strong>','<strong>|</strong>')],
 HEAD+"  <title>Recipes</title>\n</head>\n<body>\n  <h1>Jollof Meets the World</h1>\n\n  <!-- 1: add an <h2> for Naija Jollof -->\n\n  <!-- 2: add an <ol> with 3 steps -->\n\n  <!-- 3: make one word bold with <strong> -->\n\n  <!-- 4: add a second <h2> for another country's dish -->\n\n</body>\n</html>",
 HEAD+"  <title>Recipes</title>\n</head>\n<body>\n  <h1>Jollof Meets the World</h1>\n  <h2>Naija Jollof</h2>\n  <ol>\n    <li>Fry the <strong>pepper</strong> and onions.</li>\n    <li>Add rice and stock.</li>\n    <li>Cook on low heat.</li>\n  </ol>\n  <h2>Japanese Onigiri</h2>\n  <p>Rice balls with a tasty filling.</p>\n</body>\n</html>",
 [M('Add an <h2> for your jollof.','<h2>Naija Jollof</h2>',"return t.count('h2')>=1"),
  M('Add an <ol> with 3 or more steps.','<ol><li>Step one</li>...</ol>',"return t.count('ol > li')>=3"),
  M('Make some words bold with <strong>.','<strong>pepper</strong>',"return t.count('strong, b')>=1"),
  M('Add a second <h2> for a dish from another country.','Two <h2> tags in total.',"return t.count('h2')>=2")],
 'Ask: what is the best dish in your family? What goes in it?','Add the dish from your own grandmother.'))
# ---------- 3 CSS
W.append(WP('birthday-card','Birthday Card for Mama','🎂',1,['fun'],
 'Make a bright birthday card page with CSS. Colours make people smile!',
 'HTML is the skeleton. CSS is the clothes. It makes pages beautiful.',
 ['CSS rules: selector { property: value }','Colour, size and centre'],
 [('Colour the page','background-color changes the page colour.'),('Centre the heading','text-align: center puts it in the middle.'),('Make it big','font-size: 40px makes big words.'),('Colour the words','color changes text colour.')],
 ['HTML','CSS'],[('color','color: |;'),('background','background-color: |;'),('center','text-align: center;'),('size','font-size: 40px;')],
 HEAD+"  <title>Card</title>\n  <style>\n    /* write your CSS here */\n    body {\n\n    }\n    h1 {\n\n    }\n  </style>\n</head>\n<body>\n  <h1>Happy Birthday, Mama!</h1>\n  <p>You are the best.</p>\n</body>\n</html>",
 HEAD+"  <title>Card</title>\n  <style>\n    body {\n      background-color: gold;\n    }\n    h1 {\n      text-align: center;\n      font-size: 44px;\n      color: darkgreen;\n    }\n  </style>\n</head>\n<body>\n  <h1>Happy Birthday, Mama!</h1>\n  <p>You are the best.</p>\n</body>\n</html>",
 [M('Give the body a background colour.','body { background-color: gold; }',"return t.css('body','background-color')!=='rgba(0, 0, 0, 0)'"),
  M('Centre the h1.','h1 { text-align: center; }',"return t.css('h1','text-align')==='center'"),
  M('Make the h1 at least 40px big.','h1 { font-size: 44px; }',"return t.num('h1','font-size')>=40"),
  M('Give the h1 a colour that is not black.','h1 { color: darkgreen; }',"return t.css('h1','color')!=='rgb(0, 0, 0)'")],
 'Ask your mum her favourite colour. Use it!','Add a second message and style it too.'))
# ---------- 4
W.append(WP('ankara-colour-cards','Ankara Colour Cards','🧵',2,['naija-world','fun'],
 'Make three colourful cards in a row, like cloth patterns.',
 'Designers place things in rows and columns. Flexbox does this easily.',
 ['Classes','Flexbox rows','Rounded corners'],
 [('Three cards','Give each card class="card".'),('Put them in a row','display: flex on the parent puts children side by side.'),('Round the corners','border-radius makes soft corners.'),('Different colours','Give each card its own background colour.')],
 ['HTML','CSS'],[('.card','.card {\n  |\n}'),('flex','display: flex;'),('radius','border-radius: 14px;'),('gap','gap: 10px;')],
 HEAD+"  <title>Cards</title>\n  <style>\n    .row {\n      /* put the cards side by side */\n    }\n    .card {\n      padding: 16px;\n      /* round the corners */\n    }\n    /* give each card a different colour */\n  </style>\n</head>\n<body>\n  <div class=\"row\">\n    <div class=\"card\">Yoruba</div>\n    <div class=\"card\">Igbo</div>\n    <div class=\"card\">Hausa</div>\n  </div>\n</body>\n</html>",
 HEAD+"  <title>Cards</title>\n  <style>\n    .row { display: flex; gap: 10px; }\n    .card { padding: 16px; border-radius: 14px; color: white; }\n    .card:nth-child(1) { background: #c0392b; }\n    .card:nth-child(2) { background: #27ae60; }\n    .card:nth-child(3) { background: #8e44ad; }\n  </style>\n</head>\n<body>\n  <div class=\"row\">\n    <div class=\"card\">Yoruba</div>\n    <div class=\"card\">Igbo</div>\n    <div class=\"card\">Hausa</div>\n  </div>\n</body>\n</html>",
 [M('Make .row a flex row.','.row { display: flex; }',"return t.css('.row','display')==='flex'"),
  M('Round the corners of .card (8px or more).','.card { border-radius: 14px; }',"return t.num('.card','border-top-left-radius')>=8"),
  M('Give each card its own background colour.','Use .card:nth-child(1) { background: ... } and so on.',"var s={};t.all('.card').forEach(function(c){s[getComputedStyle(c).backgroundColor]=1});return Object.keys(s).length>=3 && !s['rgba(0, 0, 0, 0)']"),
  M('Keep all 3 cards.','Do not delete the cards.',"return t.count('.card')>=3")],
 'Look at a real ankara cloth. Which 3 colours do you see?','Add a fourth card for another language.'))
# ---------- 5
W.append(WP('clean-water-poster','Clean Water Poster','💧',2,['real-world'],
 'Design a hero banner that tells people why clean water matters.',
 'Good websites start with a strong first screen. We call it the hero.',
 ['Padding and space','Buttons','Hover effects'],
 [('Hero box','Give the hero a background colour and padding.'),('Big message','Make the heading large and white.'),('A button','Add a <button> people can tap.'),('Hover','a :hover rule changes the button when touched.')],
 ['HTML','CSS'],[('padding','padding: 40px 20px;'),('hover','button:hover {\n  |\n}'),('radius','border-radius: 10px;')],
 HEAD+"  <title>Water</title>\n  <style>\n    body { margin: 0; font-family: sans-serif; }\n    .hero {\n      /* colour + padding here */\n    }\n    .hero h1 {\n      /* big and white */\n    }\n    button {\n      padding: 12px 20px;\n    }\n    /* add a button:hover rule */\n  </style>\n</head>\n<body>\n  <div class=\"hero\">\n    <h1>Clean water for every child</h1>\n    <p>One tap can change a village.</p>\n    <button>Learn more</button>\n  </div>\n</body>\n</html>",
 HEAD+"  <title>Water</title>\n  <style>\n    body { margin: 0; font-family: sans-serif; }\n    .hero { background: #1e88e5; padding: 50px 20px; text-align: center; }\n    .hero h1 { font-size: 34px; color: white; }\n    .hero p { color: #e3f2fd; }\n    button { padding: 12px 20px; border: 0; border-radius: 10px; background: #ffb800; }\n    button:hover { background: #ffd54f; }\n  </style>\n</head>\n<body>\n  <div class=\"hero\">\n    <h1>Clean water for every child</h1>\n    <p>One tap can change a village.</p>\n    <button>Learn more</button>\n  </div>\n</body>\n</html>",
 [M('Give .hero a background colour.','.hero { background: #1e88e5; }',"return t.css('.hero','background-color')!=='rgba(0, 0, 0, 0)'"),
  M('Give .hero at least 30px padding on top.','.hero { padding: 50px 20px; }',"return t.num('.hero','padding-top')>=30"),
  M('Make the h1 white and at least 28px.','.hero h1 { color: white; font-size: 34px; }',"return t.css('.hero h1','color')==='rgb(255, 255, 255)' && t.num('.hero h1','font-size')>=28"),
  M('Add a button:hover rule.','button:hover { background: #ffd54f; }',"return /button\\s*:hover/.test(t.src)")],
 'Ask: where does water come from in your area?','Add a counter: "2 in 10 children need clean water" (ask your teacher for a real number).'))
# ---------- 6 responsive
W.append(WP('phone-friendly-menu','Phone-Friendly Menu','📱',2,['real-world','fun'],
 'Build a menu that looks right on a phone AND on a computer.',
 'Most Nigerian users are on phones. A good site must fit small screens.',
 ['Media queries','Flex direction','Mobile first'],
 [('Menu in a row','A <nav> with links. Flex puts them in a row.'),('Stack on small screens','@media (max-width: 600px) changes the layout on phones.'),('Column on phones','flex-direction: column stacks links.')],
 ['HTML','CSS','Responsive'],[('@media','@media (max-width: 600px) {\n  |\n}'),('flex','display: flex;'),('column','flex-direction: column;')],
 HEAD+"  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Menu</title>\n  <style>\n    body { font-family: sans-serif; margin: 0; }\n    nav ul {\n      list-style: none;\n      margin: 0;\n      padding: 10px;\n      background: #1d2433;\n      /* put the links in a row */\n    }\n    nav a { color: white; padding: 10px; text-decoration: none; }\n    /* on small screens: stack the links */\n  </style>\n</head>\n<body>\n  <nav>\n    <ul>\n      <li><a href=\"#\">Home</a></li>\n      <li><a href=\"#\">Games</a></li>\n      <li><a href=\"#\">About</a></li>\n    </ul>\n  </nav>\n</body>\n</html>",
 HEAD+"  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Menu</title>\n  <style>\n    body { font-family: sans-serif; margin: 0; }\n    nav ul { list-style: none; margin: 0; padding: 10px; background: #1d2433; display: flex; gap: 10px; }\n    nav a { color: white; padding: 10px; text-decoration: none; }\n    @media (max-width: 600px) {\n      nav ul { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n  <nav>\n    <ul>\n      <li><a href=\"#\">Home</a></li>\n      <li><a href=\"#\">Games</a></li>\n      <li><a href=\"#\">About</a></li>\n    </ul>\n  </nav>\n</body>\n</html>",
 [M('Put the menu links in a row on a big screen.','nav ul { display: flex; }',"return await t.at(900,function(){return t.css('nav ul','display')==='flex' && t.css('nav ul','flex-direction')==='row'})"),
  M('Add an @media rule.','@media (max-width: 600px) { ... }',"return t.mq().length>=1"),
  M('Stack the links in a column on a phone (360px).','Inside the media rule: nav ul { flex-direction: column; }',"return await t.at(360,function(){return t.css('nav ul','flex-direction')==='column'})"),
  M('Keep the 3 links.','Do not delete Home, Games and About.',"return t.count('nav a')>=3")],
 'Open a website on your phone. Does the menu change shape?','Add a fourth link and a logo.'))
# ---------- 7 JS calculators
W.append(WP('market-total-calculator','Market Total Calculator','🧮',3,['real-world','naija-world'],
 'Type a price and how many. The page does the sum for you!',
 'Traders add many prices every day. A calculator saves time and mistakes.',
 ['Inputs and buttons','JavaScript functions','Showing results on the page'],
 [('Read the inputs','document.getElementById("price").value gives what the user typed.'),('Do the sum','Multiply price by quantity. Use Number() to change text to a number.'),('Show it','Put the result in the page with textContent.'),('Handle empty boxes','If nothing is typed, show a friendly message.')],
 ['HTML','JavaScript'],[('getElementById','document.getElementById("|")'),('click','button.addEventListener("click", function () {\n  |\n});'),('Number','Number(|)'),('if','if (|) {\n}')],
 HEAD+"  <title>Total</title>\n</head>\n<body>\n  <h1>Market Total</h1>\n  <input id=\"price\" placeholder=\"Price in naira\">\n  <input id=\"qty\" placeholder=\"How many?\">\n  <button id=\"go\">Add up</button>\n  <p id=\"total\"></p>\n  <script>\n    var price = document.getElementById('price');\n    var qty = document.getElementById('qty');\n    var total = document.getElementById('total');\n    document.getElementById('go').addEventListener('click', function () {\n      // 1: multiply price and qty (use Number)\n      // 2: show the result in total.textContent, like: Total: N150\n      // 3: if the boxes are empty, show: Type a price and a number\n    });\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Total</title>\n</head>\n<body>\n  <h1>Market Total</h1>\n  <input id=\"price\" placeholder=\"Price in naira\">\n  <input id=\"qty\" placeholder=\"How many?\">\n  <button id=\"go\">Add up</button>\n  <p id=\"total\"></p>\n  <script>\n    var price = document.getElementById('price');\n    var qty = document.getElementById('qty');\n    var total = document.getElementById('total');\n    document.getElementById('go').addEventListener('click', function () {\n      var p = Number(price.value);\n      var q = Number(qty.value);\n      if (!p || !q) {\n        total.textContent = 'Type a price and a number';\n        return;\n      }\n      total.textContent = 'Total: N' + p * q;\n    });\n  </script>\n</body>\n</html>",
 [M('50 naira x 3 should show 150.','total.textContent = "Total: N" + p * q;',"t.type('#price','50');t.type('#qty','3');await t.click('#go');return t.text('#total').indexOf('150')>=0"),
  M('20 naira x 2 should show 40 (new numbers, new answer).','Do not write 150 in the code. Let the maths work.',"t.type('#price','20');t.type('#qty','2');await t.click('#go');return t.text('#total').indexOf('40')>=0"),
  M('Empty boxes show a friendly message.','if (!p || !q) { ... }',"t.type('#price','');t.type('#qty','');await t.click('#go');return /type|enter|number|price/i.test(t.text('#total'))"),
  M('Try 7 x 3. It should show 21.','Let the maths work for ANY numbers.',"t.type('#price','7');t.type('#qty','3');await t.click('#go');return t.text('#total').indexOf('21')>=0")],
 'Ask a trader: what do you add up the most every day?','Add a discount box that takes 10% off.'))
# ---------- 8
W.append(WP('day-night-switch','Day and Night Switch','🌗',3,['fun'],
 'A button that flips your page between day and night mode!',
 'Dark mode helps eyes at night and saves phone battery.',
 ['classList.toggle','CSS classes that change the look','Events'],
 [('Make a .night style','In CSS write .night { background: #111; color: white; }.'),('Find the button','Use document.getElementById.'),('Toggle on click','document.body.classList.toggle("night") switches it.'),('Change the button words','Say "Go to day" or "Go to night".')],
 ['HTML','CSS','JavaScript'],[('toggle','document.body.classList.toggle("night");'),('click','btn.addEventListener("click", function () {\n  |\n});')],
 HEAD+"  <title>Switch</title>\n  <style>\n    body { font-family: sans-serif; padding: 20px; background: #fffaf0; color: #1d2433; }\n    /* 1: add a .night rule: dark background, light text */\n  </style>\n</head>\n<body>\n  <h1>Hello, world</h1>\n  <button id=\"sw\">Go to night</button>\n  <script>\n    var btn = document.getElementById('sw');\n    // 2: on click, toggle the class night on document.body\n    // 3: change the button text to match\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Switch</title>\n  <style>\n    body { font-family: sans-serif; padding: 20px; background: #fffaf0; color: #1d2433; }\n    body.night { background: #111; color: white; }\n  </style>\n</head>\n<body>\n  <h1>Hello, world</h1>\n  <button id=\"sw\">Go to night</button>\n  <script>\n    var btn = document.getElementById('sw');\n    btn.addEventListener('click', function () {\n      document.body.classList.toggle('night');\n      btn.textContent = document.body.classList.contains('night') ? 'Go to day' : 'Go to night';\n    });\n  </script>\n</body>\n</html>",
 [M('Add a body.night (or .night) rule in CSS.','.night { background: #111; color: white; }',"return /\\.night/.test(t.src)"),
  M('Clicking the button gives the body the class night.','classList.toggle("night")',"document.body.classList.remove('night');await t.click('#sw');return document.body.classList.contains('night')"),
  M('The page background really changes to dark.','Check your .night background colour.',"document.body.classList.remove('night');await t.click('#sw');var c=t.css('body','background-color');return c!=='rgb(255, 250, 240)' && c!=='rgba(0, 0, 0, 0)'"),
  M('Click again to go back to day.','toggle adds AND removes.',"document.body.classList.remove('night');await t.click('#sw');var a=document.body.classList.contains('night');await t.click('#sw');return a && !document.body.classList.contains('night')")],
 'Ask: do you like dark mode on your phone? Why?','Add a third mode: Nigerian green.'))
# ---------- 9
W.append(WP('which-country-quiz','Which Country? Quiz','🌍',3,['naija-world','fun'],
 'A one-question quiz that says "Correct!" or "Try again".',
 'Quizzes teach by asking. They use if / else, just like Scratch.',
 ['Buttons that react','if / else in JavaScript','Changing text'],
 [('Make buttons','Each answer is a <button>.'),('Know which one is right','Use an if to check.'),('Say the result','Show Correct! or Try again.')],
 ['HTML','JavaScript'],[('if/else','if (|) {\n} else {\n}'),('click','a.addEventListener("click", function () {\n  |\n});')],
 HEAD+"  <title>Quiz</title>\n</head>\n<body>\n  <h1>Which country has the city of Lagos?</h1>\n  <button id=\"a\">Ghana</button>\n  <button id=\"b\">Nigeria</button>\n  <button id=\"c\">Kenya</button>\n  <p id=\"msg\"></p>\n  <script>\n    var msg = document.getElementById('msg');\n    function answer(isRight) {\n      // 1: if isRight, show Correct! in msg, else show Try again\n    }\n    // 2: when button b is clicked call answer(true)\n    // 3: when button a or c is clicked call answer(false)\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Quiz</title>\n</head>\n<body>\n  <h1>Which country has the city of Lagos?</h1>\n  <button id=\"a\">Ghana</button>\n  <button id=\"b\">Nigeria</button>\n  <button id=\"c\">Kenya</button>\n  <p id=\"msg\"></p>\n  <script>\n    var msg = document.getElementById('msg');\n    function answer(isRight) {\n      if (isRight) { msg.textContent = 'Correct!'; }\n      else { msg.textContent = 'Try again'; }\n    }\n    document.getElementById('b').addEventListener('click', function () { answer(true); });\n    document.getElementById('a').addEventListener('click', function () { answer(false); });\n    document.getElementById('c').addEventListener('click', function () { answer(false); });\n  </script>\n</body>\n</html>",
 [M('Clicking Nigeria shows Correct!','answer(true) when b is clicked.',"await t.click('#b');return /correct/i.test(t.text('#msg'))"),
  M('Clicking Ghana shows Try again.','answer(false) when a is clicked.',"await t.click('#a');return /try again/i.test(t.text('#msg'))"),
  M('Clicking Kenya shows Try again.','answer(false) when c is clicked.',"await t.click('#c');return /try again/i.test(t.text('#msg'))"),
  M('Use if and else in answer().','if (isRight) { ... } else { ... }',"return /if\\s*\\(/.test(t.src) && /else/.test(t.src)")],
 'Ask a friend a question about your country and add it.','Add a score that goes up for every right answer.'))
# ---------- 10
W.append(WP('language-greeter','Language Greeter','🗣️',3,['naija-world','fun'],
 'Pick a language from a menu and the page says hello in it.',
 'Real apps look things up in a list. In JavaScript the list is an object.',
 ['Objects as lookup tables','The select menu','Reacting to change'],
 [('Make the menu','A <select> with <option> choices.'),('Store greetings','var hello = { yoruba: "Bawo ni", ... }'),('Look up and show','hello[select.value] gives the greeting.')],
 ['HTML','JavaScript'],[('object','var hello = {\n  yoruba: "|"\n};'),('change','sel.addEventListener("change", function () {\n  |\n});')],
 HEAD+"  <title>Greeter</title>\n</head>\n<body>\n  <h1>Say hello</h1>\n  <select id=\"lang\">\n    <option value=\"yoruba\">Yoruba</option>\n    <option value=\"igbo\">Igbo</option>\n    <option value=\"hausa\">Hausa</option>\n    <option value=\"french\">French</option>\n  </select>\n  <p id=\"out\"></p>\n  <script>\n    var sel = document.getElementById('lang');\n    var out = document.getElementById('out');\n    // 1: make an object hello with the 4 greetings\n    // Yoruba: Bawo ni, Igbo: Kedu, Hausa: Sannu, French: Bonjour\n    // 2: when the menu changes, show hello[sel.value] in out\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Greeter</title>\n</head>\n<body>\n  <h1>Say hello</h1>\n  <select id=\"lang\">\n    <option value=\"yoruba\">Yoruba</option>\n    <option value=\"igbo\">Igbo</option>\n    <option value=\"hausa\">Hausa</option>\n    <option value=\"french\">French</option>\n  </select>\n  <p id=\"out\"></p>\n  <script>\n    var sel = document.getElementById('lang');\n    var out = document.getElementById('out');\n    var hello = { yoruba: 'Bawo ni', igbo: 'Kedu', hausa: 'Sannu', french: 'Bonjour' };\n    sel.addEventListener('change', function () {\n      out.textContent = hello[sel.value];\n    });\n  </script>\n</body>\n</html>",
 [M('Choosing Yoruba shows Bawo ni.','hello.yoruba = "Bawo ni"',"t.type('#lang','yoruba');return /bawo ni/i.test(t.text('#out'))"),
  M('Choosing Igbo shows Kedu.','hello.igbo = "Kedu"',"t.type('#lang','igbo');return /kedu/i.test(t.text('#out'))"),
  M('Choosing Hausa shows Sannu.','hello.hausa = "Sannu"',"t.type('#lang','hausa');return /sannu/i.test(t.text('#out'))"),
  M('Choosing French shows Bonjour.','hello.french = "Bonjour"',"t.type('#lang','french');return /bonjour/i.test(t.text('#out'))")],
 'Ask a friend to teach you hello in their language.','Add a fifth language from your family.'))
