W.append(WP('good-habit-tracker','Good Habit Tracker','✅',3,['real-world'],
 'Add habits to a list and tick them off. Like a real app!',
 'Apps that help people build habits (like washing hands) use lists you can add to.',
 ['Creating elements with JavaScript','Arrays vs the page','Click to toggle a style'],
 [('Add a habit','Read the input and make a new <li>.'),('Put it on the page','list.appendChild(li) adds it.'),('Tick it off','Clicking an item adds the class "done".'),('Clear the box','After adding, set input.value = "".')],
 ['HTML','CSS','JavaScript'],[('create','var li = document.createElement("li");'),('append','list.appendChild(li);'),('toggle','li.classList.toggle("done");')],
 HEAD+"  <title>Habits</title>\n  <style>\n    .done { text-decoration: line-through; color: gray; }\n    li { cursor: pointer; }\n  </style>\n</head>\n<body>\n  <h1>My good habits</h1>\n  <input id=\"habit\" placeholder=\"e.g. wash hands\">\n  <button id=\"add\">Add</button>\n  <ul id=\"list\"></ul>\n  <script>\n    var input = document.getElementById('habit');\n    var list = document.getElementById('list');\n    document.getElementById('add').addEventListener('click', function () {\n      // 1: if the input is empty, stop (return)\n      // 2: make a new li with the text, add it to list\n      // 3: clicking the li toggles the class done\n      // 4: clear the input\n    });\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Habits</title>\n  <style>\n    .done { text-decoration: line-through; color: gray; }\n    li { cursor: pointer; }\n  </style>\n</head>\n<body>\n  <h1>My good habits</h1>\n  <input id=\"habit\" placeholder=\"e.g. wash hands\">\n  <button id=\"add\">Add</button>\n  <ul id=\"list\"></ul>\n  <script>\n    var input = document.getElementById('habit');\n    var list = document.getElementById('list');\n    document.getElementById('add').addEventListener('click', function () {\n      var text = input.value.trim();\n      if (!text) { return; }\n      var li = document.createElement('li');\n      li.textContent = text;\n      li.addEventListener('click', function () { li.classList.toggle('done'); });\n      list.appendChild(li);\n      input.value = '';\n    });\n  </script>\n</body>\n</html>",
 [M('Typing a habit and pressing Add puts it in the list.','Create an li and appendChild it.',"t.type('#habit','wash hands');await t.click('#add');return t.count('#list li')===1 && /wash hands/.test(t.text('#list li'))"),
  M('Empty input adds nothing.','if (!text) { return; }',"t.type('#habit','');await t.click('#add');return t.count('#list li')===1"),
  M('The input box clears after adding.','input.value = "";',"t.type('#habit','read a book');await t.click('#add');return t.$('#habit').value===''"),
  M('Clicking a habit gives it the class done.','li.classList.toggle("done")',"await t.click('#list li');return t.has('#list li.done')")],
 'Ask your family: what is one good habit that helps you?','Add a delete button next to each habit.'))
